#!/usr/bin/env python3
"""Source-specific batch5 patient facts. External feasibility draft, not prescribing authority."""
import copy,json,pathlib
HERE=pathlib.Path(__file__).resolve().parent
DATE='2026-11-18'; VERSION='0.84.64'
ROUTES={c:c for c in ['00675','00747','00504','00754','00757']}
MANIFEST=json.loads((HERE/'source-review/nccp-source-manifest.json').read_text())
SOURCES={s['code']:dict(catalogue_url=s['source_url'],pages=s['source_pages'],version=s['version'])for s in MANIFEST['sources']}
ACCESS='The treatment service chooses suitable intravenous access. Report burning, pain, swelling or redness during administration immediately. If a port or central catheter is used, agree dressing, flushing, infection precautions and eventual removal arrangements. Do not alter infusion or mesna-pump settings yourself.'
FERTILITY='Discuss fertility preservation before treatment; these combinations can permanently affect fertility. Obtain a written pregnancy-prevention, contraception and breastfeeding plan covering every medicine and the longest relevant precaution period. Current product instructions differ from the older general six-month regimen paragraph. Do not assume one interval applies to everyone, and contact oncology promptly if pregnancy is possible.'
FLUIDS='Ifosfamide needs prescribed intravenous hydration before treatment and continuing until 24 hours after it finishes, with mesna bladder protection. Staff monitor urine output, fluid balance and weight and adjust fluids for the individual. These hospital fluid prescriptions are not instructions to drink a fixed amount at home; tell the team about heart problems or fluid restriction. Protective treatment after an administered dose must not be stopped just because a later chemotherapy dose is held.'
DIARRHOEA='Irinotecan can cause two different bowel problems. Cramping, sweating and diarrhoea during or shortly after infusion can be an acute cholinergic reaction: tell the nurse immediately; prescribed atropine may be used. Delayed diarrhoea begins more than 24 hours later and can cause dangerous dehydration or infection. Contact oncology at the first loose stool and follow the written anti-diarrhoeal and rehydration prescription. Fever, severe pain, blood, faintness, very little urine or inability to drink needs immediate assessment; never wait for a time threshold when seriously unwell.'
DIARRHOEA_CLINICIAN='The source adult loperamide reference is 4 mg initially, then 2 mg every 2 hours, continuing for 12 hours after the last liquid stool, but not longer than 48 hours at this dose. This requires the prescribed local adult plan and is not a paediatric dose or prophylactic instruction. Persistent diarrhoea beyond 48 hours despite this plan, fever or severe illness requires urgent reassessment/hospital care. Oral cefixime may be considered in adults at 400 mg daily from day −2 to day +7; it is not a universal or paediatric prescription.'
NCI_EWING='https://www.cancer.gov/types/bone/hp/ewing-treatment-pdq'
NCI_RMS='https://www.cancer.gov/types/soft-tissue-sarcoma/hp/rhabdomyosarcoma-treatment-pdq'

def test(label,purpose,timing,kind='blood',scope='routine',sources=None):
 return dict(label=label,purpose=purpose,timing=timing,kind=kind,scope=scope,source_ids=sources or ['nccp'])
def summary(stage,name,when,basis='Regimen'):
 return dict(stage=stage,test=name,when=when,basis=basis)
def track(id,label,start,end,text,style='treatment'):
 return dict(id=id,label=label,start=start,end=end,text=text,style=style)
def anatomy(code):
 names={'00675':'Alternating chemotherapy','00747':'Alternating chemotherapy','00754':'Ifosfamide, vincristine, doxorubicin and dactinomycin','00504':'Irinotecan and temozolomide','00757':'Vincristine, irinotecan and temozolomide'}[code]
 common=[['mouth','Mouth and appetite',names,'Report mouth sores or trouble drinking early. Use the prescribed mouth-care and anti-sickness plan.',50,13],['liver','Liver',names,'Blood tests check liver effects. Yellow eyes, dark urine or significant upper abdominal pain needs prompt advice.',43,33],['blood','Blood cells',names,'Fever, shaking chills, sudden illness or unusual bleeding needs immediate oncology contact.',64,55]]
 if code in ['00675','00747','00754']:
  rows=[['brain','Brain and alertness','Ifosfamide','New confusion, unusual sleepiness, hallucinations, unsteadiness or seizures needs urgent assessment.',50,8],common[0],['heart','Heart','Doxorubicin','Report breathlessness, chest pain, swelling or palpitations. Previous anthracycline treatment affects the safe plan.',48,25],common[1],['kidneys','Kidneys and bladder','Ifosfamide'+(' and cyclophosphamide'if code!='00754'else''),'Mesna and fluids protect the bladder. Report painful urination, blood or clots, or reduced urine promptly.',39.5,38.6],['bowel','Bowel movement','Vincristine','Constipation can become severe. Abdominal pain or swelling with vomiting or inability to pass stool needs urgent advice.',50,44.5],common[2],['nerves','Nerves','Vincristine','Report numbness, tingling, weakness, walking difficulty, jaw pain or a changed voice before another dose.',35,77]]
 else:
  rows=[common[0],['lungs','Lungs and infection','Temozolomide','New cough or breathlessness needs urgent assessment. Take the prescribed infection-prevention medicine.',61.5,24.7],common[1],['kidneys','Hydration and kidneys','Irinotecan','Diarrhoea or vomiting can cause dehydration. Very little urine, dizziness or inability to drink needs urgent help.',39.5,38.6],['bowel','Bowel','Irinotecan'+(' and vincristine'if code=='00757'else''),'Report diarrhoea immediately and follow the written plan. Severe pain, fever or persistent vomiting needs urgent help.',50,44.5],common[2],['skin','Skin and infusion site',names,'Report rash and line-site pain early. Blistering or peeling skin or sores involving the eyes needs urgent assessment.',65,70],['nerves' if code=='00757'else'brain','Nerves'if code=='00757'else'Alertness and daily life','Vincristine'if code=='00757'else'Treatment and illness','Report new numbness, weakness, walking difficulty or severe constipation before another dose.'if code=='00757'else'Fatigue and dizziness can affect daily tasks. Sudden confusion, collapse or seizures needs emergency assessment.',35 if code=='00757'else 50,77 if code=='00757'else 8]]
 return rows

def ie_calendar(code):
 days=14 if code=='00675'else 21
 groups=[('ie','Ifosfamide and etoposide: cycles 1, 3, 5, 7, 9, 11 and 13',[1,3,5,7,9,11,13],['ifosfamide','etoposide'],[track('etoposide','Etoposide',1,5,'100 mg/m² each day; 60-minute infusion.'),track('ifosfamide','Ifosfamide',1,5,'1800 mg/m² each day; 60-minute infusion.'),track('mesna','Mesna bladder protection',1,5,'Each treatment day: before ifosfamide and 4 and 8 hours after its START.','support')]),('vac','Vincristine, doxorubicin and cyclophosphamide: cycles 2, 4, 6, 8 and 10',[2,4,6,8,10],['vincristine','doxorubicin','cyclophosphamide'],[track('vincristine','Vincristine',1,1,'1.5 mg/m², maximum 2 mg.'),track('doxorubicin','Doxorubicin',1,1,'75 mg/m²; cumulative exposure reviewed.'),track('cyclophosphamide','Cyclophosphamide',1,1,'1200 mg/m²; additional mesna if pelvic radiotherapy is planned.')]),('vc','Vincristine and cyclophosphamide: cycles 12 and 14',[12,14],['vincristine','cyclophosphamide','dactinomycin'],[track('vincristine','Vincristine',1,1,'1.5 mg/m², maximum 2 mg.'),track('cyclophosphamide','Cyclophosphamide',1,1,'1200 mg/m².'),track('dactinomycin','Dactinomycin ONLY if selected',1,1,'Optional consultant decision: 1.25 mg/m², maximum 2.5 mg. No doxorubicin.')])]
 out=[]
 for id,label,cycles,agents,rows in groups:
  if code=='00675':rows.append(track('growth-factor','White-cell growth factor',8 if id=='ie'else 2,13 if id=='ie'else 3,'Daily injections on days 8–13 after ifosfamide/etoposide.'if id=='ie'else'Pegylated injection 24–48 hours after chemotherapy; actual time is prescribed.','support'))
  else:rows.append(track('growth-factor','White-cell growth-factor plan',1,days,'Required after every cycle; product and timing follow the individual local prescription.','support'))
  rows.append(track('checks','Checks and symptom reporting',1,days,'Report symptoms promptly and follow the named test schedule.','monitoring'))
  out.append(dict(id=id,label=label,cycles=cycles,agents=agents,cycle_days=days,timeline=rows,schedule_summary=label+'. Repeats at the prescribed interval only after safety review.',chronology_notes=[dict(title='Phase identity',text='Use the numbered administration in the whole 14-administration programme. These are not 14 pairs.'),dict(title='Optional medicine',text='Dactinomycin is only considered in cycles 12 and 14 and is not automatically prescribed.'),dict(title='Local treatment',text='Surgery and radiotherapy have separate confirmed appointments; drug order or timing can change.')]))
 return out

def ivado_calendar():
 out=[]
 for id,label,cycles,vdays,dox in [('early','Cycles 1–2: additional vincristine visits',[1,2],[1,8,15],True),('middle','Cycles 3–4: vincristine on day 1',[3,4],[1],True),('late','Cycles 5–9: no doxorubicin',[5,6,7,8,9],[1],False)]:
  rows=[track('vincristine'+str(n),'Vincristine day '+str(n),n,n,'1.5 mg/m², maximum 2 mg.')for n in vdays]
  rows += [track('dactinomycin','Dactinomycin',1,1,'1.5 mg/m², maximum 2 mg.'),track('ifosfamide','Ifosfamide',1,2,'3000 mg/m² each day; 3-hour infusion.'),track('mesna','Mesna bladder protection',1,2,'Each day: 900 mg/m² before ifosfamide, then 3000 mg/m² continuously over 24 hours.','support')]
  if dox:rows.insert(0,track('doxorubicin','Doxorubicin',1,2,'30 mg/m² each day; only cycles 1–4.'))
  if id=='early':rows += [track('growth-factor1','White-cell growth factor',4,7,'Prescribed daily injections.','support'),track('growth-factor2','White-cell growth factor',9,11,'Second prescribed daily course.','support')]
  else:rows.append(track('growth-factor','White-cell growth-factor review',4,4,'Consider pegylated growth factor from day 4 if prescribed.','support'))
  rows.append(track('checks','Checks and symptoms',1,21,'Use the named test and urgent-contact plan.','monitoring'))
  out.append(dict(id=id,label=label,cycles=cycles,agents=['ifosfamide','vincristine','dactinomycin']+(['doxorubicin']if dox else[]),cycle_days=21,timeline=rows,schedule_summary=label+'. Ifosfamide continues on days 1 and 2 in all three phases.',chronology_notes=[dict(title='Phase switch',text='Days 8 and 15 vincristine apply only to cycles 1 and 2. Doxorubicin stops after cycle 4.'),dict(title='Protection continues',text='Mesna and prescribed fluids protect against an already administered dose; follow their actual finish times.')]))
 return out

def facts():
 packet=json.loads((HERE/'source-review/agent-consent-definitions.json').read_text());a=packet['agents'];out={}
 for code in ['00675','00747']:
  days=14 if code=='00675'else 21;age='Adolescents and young adults'if code=='00675'else'Adults'
  heart='Before treatment if clinically indicated; repeat when indicated.'if code=='00675'else'Before treatment if older than 65 years or clinically indicated; repeat when indicated.'
  growth='White-cell growth-factor support is required after every cycle. After vincristine/cyclophosphamide-containing cycles, pegylated growth factor is given 24–48 hours after chemotherapy. After ifosfamide/etoposide, daily growth factor is given on days 8–13; the source dose is 0.5 million units/kg, capped at 48 million units/day for primary prevention.'if code=='00675'else'White-cell growth-factor support is required after every cycle. The standard or pegylated product and its exact timing follow the local prescription; the two-week regimen’s day 8–13 instruction must not be imported here.'
  schedule=f'There are 14 alternating administrations, planned every {days} days after recovery, not 14 pairs. Ifosfamide and etoposide are given on days 1–5 in cycles 1, 3, 5, 7, 9, 11 and 13. Vincristine, doxorubicin and cyclophosphamide are given on day 1 in cycles 2, 4, 6, 8 and 10. Cycles 12 and 14 contain vincristine and cyclophosphamide with no doxorubicin; dactinomycin may be added only if the consultant selects it. Surgery, radiotherapy, toxicity or delayed recovery may change the sequence or dates.'
  out[code]=dict(title=f'Alternating ifosfamide/etoposide and vincristine/doxorubicin/cyclophosphamide · every {days//7} weeks',context=age+' with newly diagnosed Ewing-family sarcoma, or the separately listed rhabdomyosarcoma/desmoplastic intra-abdominal small round blue cell tumour indication',purpose='Treat cancer throughout the body as part of a specialist plan that also addresses local tumour control. The intended benefit depends on the exact tumour, disease extent and treatment aim.',days=days,kind='alternating-cycles',label=f'14 alternating administrations · usually every {days} days',agents=[copy.deepcopy(a[n])for n in ['ifosfamide','etoposide','vincristine','doxorubicin','cyclophosphamide','dactinomycin']],schedule=schedule,administration='During ifosfamide/etoposide cycles, each medicine is infused over 60 minutes on each of days 1–5. During the alternating day-1 cycles, vincristine is given by an intravenous minibag over 15 minutes, conventional doxorubicin by slow intravenous bolus, and cyclophosphamide over 30 minutes. Optional final-phase dactinomycin is given by trained staff. Mesna, fluids, tests and observation add substantially to attendance time.',baseline='Full blood count, kidney and liver profile, sodium, potassium and phosphate. Review neurological function, urine, cumulative anthracycline exposure, cardiac risk, medicines, fertility and the surgery/radiotherapy plan.',monitoring='Blood count, kidney and liver tests before each cycle; sodium, potassium and phosphate before ifosfamide/etoposide cycles. Check neurological function before every ifosfamide dose and urine for blood before every dose and every 8 hours on treatment days. Heart function is reviewed when indicated.',support='All phases require a prescribed high-risk anti-sickness plan. Review interactions involving aprepitant, ifosfamide and vincristine. '+growth+' '+FLUIDS,prep='Confirm the current numbered administration and which drugs it contains. Review constipation prevention, mouth care, medicines and infection contacts. If pelvic radiotherapy is planned, the team prescribes additional mesna with cyclophosphamide. Confirm the timing of chemotherapy around radiation.',access=ACCESS,wider='For Ewing sarcoma, systemic chemotherapy is combined with surgery and/or radiotherapy for local tumour control. For rhabdomyosarcoma, the specialist combines systemic and local treatment according to site, risk and feasibility. These decisions require the relevant multidisciplinary team; Ewing trial percentages cannot be used as estimates for the other listed tumour types. Rehabilitation, symptom control and psychological support can accompany cancer treatment.',scope=f'This is the {days}-day national schedule for {age.lower()}. No numerical age or performance-status boundary is added where the source does not supply one. The treatment starts with ifosfamide/etoposide. The final two even-numbered administrations omit doxorubicin, and dactinomycin remains optional. Trial schedules and other age-group protocols are not interchangeable.',trial='Interval-compressed versus three-weekly chemotherapy in localised Ewing sarcoma',trial_url='https://pmc.ncbi.nlm.nih.gov/articles/PMC3494838/',evidence='In a randomised trial of predominantly children and adolescents with localised Ewing sarcoma, giving alternating chemotherapy every two weeks improved event-free survival compared with every three weeks. Longer follow-up of the same study supported sustained benefit. This evidence informs interval choice but does not make the individual national calendars identical to the study.',caveat='The trial population was mostly young and had localised Ewing sarcoma. It began with vincristine/doxorubicin/cyclophosphamide, whereas these national schedules begin with ifosfamide/etoposide; some doses and recovery thresholds also differ. Do not transfer Ewing outcomes to rhabdomyosarcoma, desmoplastic tumours, metastatic disease or every adult. Long-term follow-up is the same cohort, not an independent trial.',doses=[('ie','Ifosfamide and etoposide',1,5,'Shown only for odd-numbered cycles; use the separate phase charts.')],phases=[('ie','Odd cycles: ifosfamide and etoposide',['Ifosfamide','Etoposide'],'high'),('vac','Cycles 2, 4, 6, 8 and 10',['Vincristine','Doxorubicin','Cyclophosphamide'],'high'),('vc','Cycles 12 and 14; dactinomycin only if selected',['Vincristine','Cyclophosphamide','Dactinomycin only if prescribed'],'high')],course='14 administrations, with individually confirmed dates',urgent='Confusion or unusual drowsiness during ifosfamide, blood in urine, reduced urine, severe constipation, new weakness or heart symptoms needs urgent assessment. Doxorubicin can colour urine red for one or two days; do not dismiss painful urination, clots or suspected blood as harmless colour.',boundaries=['Do not exceed the source doxorubicin lifetime ceiling of 375 mg/m² without specialist reconciliation of previous anthracycline exposure. The five planned 75 mg/m² doses reach that ceiling.','Mesna after ifosfamide is timed from the START of the infusion, not its finish; 360 mg/m² intravenously before, and 4 and 8 hours after the start on each treatment day.','When pelvic radiotherapy is planned, cyclophosphamide protection is mesna 240 mg/m² intravenously before it, then either 240 mg/m² intravenously or 480 mg/m² orally at 4 and 8 hours from its start. These route-dependent doses are not interchangeable.','Doxorubicin may be omitted during radiotherapy depending on the field and is not reintroduced until at least three weeks after radiotherapy ends. Vincristine product information has a separate liver-field radiation precaution.','Hospital hydration is individually prescribed. Source surveillance includes urine output at least 100 mL/hour, strict fluid balance and daily weight; positive balance above 1 litre or weight gain above 1 kg needs review. These are clinical monitoring criteria, not home fluid targets.','Current etoposide, cyclophosphamide, ifosfamide and vincristine product organ-impairment wording may differ from national tables; reconcile the supplied products and retain safety-history stops.'],tests=[test('Full blood count','Check infection-fighting cells, anaemia and bleeding risk.','Before treatment and each cycle; further samples are directed by symptoms, recovery or the prescribed admission plan.'),test('Kidney, liver and electrolytes','Detect organ injury and electrolyte loss that affect treatment safety.','Kidney and liver tests at baseline and before every cycle. Sodium, potassium and phosphate at baseline and before each ifosfamide/etoposide cycle; repeat when clinically indicated.'),test('Neurological function','Detect ifosfamide-related changes in alertness and vincristine nerve toxicity.','Assess alertness and neurological function before every ifosfamide dose. Report numbness, weakness, bowel slowing or walking changes before further vincristine.','review'),test('Urine, fluid balance and weight','Detect bladder bleeding, kidney effects and fluid retention despite protective treatment.','Check urine for blood before each ifosfamide dose and every 8 hours on treatment days. Staff monitor urine output and fluid balance and weigh daily during the prescribed hydration period.','review'),test('Heart pumping and anthracycline exposure','Assess cardiac safety before further doxorubicin. ',heart+' Heart ultrasound or a pumping scan measures left ventricular ejection fraction; the national source requires greater than 50% for doxorubicin. Review symptoms, previous anthracyclines and radiation exposure before further dosing.','procedure','conditional')],summary_monitoring=[summary('Bloods','Blood count, kidney and liver','Before treatment and each cycle.'),summary('Bloods','Sodium, potassium and phosphate','Before treatment and each ifosfamide/etoposide cycle.'),summary('Checks','Nerves, urine and fluid balance','Nerve/alertness and urine checks before each ifosfamide dose; urine every 8 hours on treatment days; fluid balance and daily weight.'),summary('Heart','Heart pumping and previous doses',heart+' The team reviews lifetime doxorubicin exposure.'),summary('Review','Tumour and local-treatment plan','Scans, surgery and radiotherapy reviews follow your individual specialist plan.','Individual plan')],phase_cycles=ie_calendar(code),wider_sources=['nci-ewing','nci-rms'])
  out[code]['agents'][-1]['name']='Dactinomycin · only if selected for cycles 12 and 14'
  out[code]['agents'][-1]['explanation']='This medicine is optional in the final two even-numbered administrations and is included in your consent only if selected. '+out[code]['agents'][-1]['explanation']
 return complete_other(out,a)

def complete_other(out,a):
 for code in ['00504','00757']:
  vit=code=='00757';names=['vincristine','irinotecan','temozolomide']if vit else['irinotecan','temozolomide'];cycles=12 if vit else 6
  tmz='125 mg/m² in cycle 1; only the treating team may select 150 mg/m² from cycle 2 after reviewing toxicity'if vit else'100 mg/m²'
  schedule=f'Irinotecan 50 mg/m² intravenously and temozolomide {tmz} by mouth are given on days 1–5 of each 21-day cycle. '+('Vincristine 1.5 mg/m², maximum 2 mg, is given on days 1 and 8. 'if vit else'')+f'The national plan specifies {cycles} cycles unless progression, toxicity or the specialist plan changes treatment. Take temozolomide fasting, swallowed whole with water, at least one hour before irinotecan. If you vomit after temozolomide, do not take an extra dose.'
  missed='If a temozolomide dose is missed, contact the treatment team promptly so timing with irinotecan can be confirmed. The national source allows making up a missed dose unless the next dose is due within 12 hours; never double a dose or restart a held course yourself.'if vit else'If a temozolomide dose is missed, contact the treatment team for instructions; this regimen does not supply the other regimen’s 12-hour make-up rule. Never double a dose or restart a held course yourself.'
  out[code]=dict(title='Vincristine, irinotecan and temozolomide'if vit else'Irinotecan and temozolomide',context='Relapsed or refractory rhabdomyosarcoma'if vit else'Relapsed or refractory Ewing sarcoma',purpose='Aim to shrink or control cancer and help symptoms after previous treatment. Your specialist explains the realistic benefit, uncertainty and alternatives for your particular disease.',days=21,kind='cycle',label=f'Days 1–5'+(' and day 8 vincristine'if vit else'')+f' · every 21 days · {cycles} planned cycles',agents=[copy.deepcopy(a[n])for n in names],schedule=schedule,administration='Irinotecan is infused over 60 minutes after the oral temozolomide dose, with prescribed anti-sickness and bowel protection. '+('Vincristine is administered only into a vein using a minibag over 15 minutes. 'if vit else'')+'Confirm which doses are taken at home or in the unit and bring the exact capsule prescription; capsule strengths can differ.',baseline='Full blood count, kidney and liver profile and hepatitis B screening. '+('Check blood glucose and nerve symptoms. 'if vit else'')+'Review bowel function, medicines, infection risk, pregnancy/fertility plans and the ability to take and safely handle capsules.',monitoring='Blood count, kidney and liver tests before each cycle and additional checks when required by symptoms or product guidance. '+('Review peripheral neuropathy each cycle and before every vincristine dose. 'if vit else'')+'Track diarrhoea and hydration, infections and any previous dose holds; improving symptoms alone does not authorise restarting.',support='Irinotecan has moderate nausea/vomiting risk and temozolomide moderate-to-high risk; use the individually prescribed multi-day anti-sickness plan and required prevention against Pneumocystis jirovecii pneumonia, a potentially serious opportunistic lung infection. '+('The source lists atropine 250 micrograms under the skin before irinotecan; the team confirms suitability and age-appropriate prescription, especially with glaucoma. Constipation prevention is recommended; an antifungal may be considered, but azole antifungals interact with vincristine. 'if vit else'The source lists atropine prophylaxis without a fixed dose; the team confirms suitability, especially with glaucoma. ')+DIARRHOEA,prep='Agree a written early-reaction and delayed-diarrhoea plan, the infection-prevention prescription, capsule timing and urgent contacts. Review all medicines and supplements; do not start antidiarrhoeals preventively or change an antibiotic yourself. '+missed,access=ACCESS+' Keep temozolomide in its supplied packaging; do not crush or open capsules. Ask the pharmacy how carers should handle the medicine and what to do after a damaged capsule or spill.',wider='The specialist sarcoma team reviews prior treatments, disease sites, symptoms, available further systemic options and suitable clinical trials. Selected surgery or radiotherapy may help local control or symptoms; it is not automatically part of this capsule/infusion calendar. Symptom-focused treatment, rehabilitation and supportive or palliative care remain options alongside or instead of further chemotherapy.',scope=('The live national catalogue places this in adult treatment, while the PDF includes a wider age range and age-specific performance scales. Paediatric use requires the appropriate specialist pathway, not automatic extension of this adult portal. Temozolomide escalation and reduction depend on actual previous doses and toxicity; a recovered grade does not erase prior events. 'if vit else'This is the 50 mg/m² irinotecan, 100 mg/m² temozolomide, six-cycle Ewing regimen. Other published schedules and the vincristine-containing rhabdomyosarcoma regimen are different. ')+'The national source identifies unlicensed indication use: the team must explain the rationale and document consent under local policy, including the source drug-and-therapeutics committee requirement.',trial='Randomised vincristine/irinotecan with or without temozolomide in relapsed rhabdomyosarcoma'if vit else'rEECur interim irinotecan/temozolomide report and adult-containing retrospective Ewing series',trial_url='https://ascopubs.org/doi/abs/10.1200/JCO.21.00124'if vit else'https://doi.org/10.1200/JCO.2020.38.15_suppl.11502',evidence='A randomised study found a higher observed response and longer overall survival with the three-drug combination than with vincristine/irinotecan alone, but the primary response comparison did not meet conventional statistical significance and severe adverse events were more frequent. Most participants were children; adult-specific benefit cannot be assumed.'if vit else'Prospective interim trial evidence and retrospective studies show activity in some relapsed Ewing sarcomas. In the rEECur comparison, the irinotecan/temozolomide arm was less effective than the other then-open arms and was closed. The existence of responses does not establish superiority or an individual chance of benefit.',caveat='The primary response endpoint had P=0.09; progression-free survival also did not reach conventional significance. The overall-survival result is a separate endpoint. The trial treated until progression or unacceptable toxicity, whereas the national schedule specifies 12 cycles. Mixed ages do not establish a separate adult estimate.'if vit else'The rEECur figures are from an interim conference report, not a completed full-paper comparison. Retrospective series are subject to selection bias; the adult-containing Palmerini series used irinotecan 40 mg/m², not this national 50 mg/m² schedule. Disease control includes stable disease and must not be labelled response.',doses=([('vin1','Vincristine',1,1,'Only into a vein; 1.5 mg/m², maximum 2 mg.'),('vin8','Vincristine',8,8,'Separate safety and nerve review before day 8.')]if vit else[])+[('temozolomide','Temozolomide',1,5,'Fasting, whole capsules, at least one hour before irinotecan; use the actual prescribed dose.'),('irinotecan','Irinotecan',1,5,'50 mg/m² over 60 minutes each day.')],phases=[('combination','Days 1–5: irinotecan and temozolomide'+(' with day 1 vincristine'if vit else''),[a[n]['name']for n in names],'moderate-to-high')]+([('vin8','Day 8: vincristine only',['Vincristine'],'minimal')]if vit else[]),course=f'{cycles} planned cycles; continuation depends on specialist review',urgent=DIARRHOEA+' Report a new cough, breathlessness, jaundice, severe rash or marked weakness urgently.',boundaries=['Document off-label indication discussion and the local governance/consent requirements stated in the national source.','Review baseline infection, bowel status and UGT1A1*28 homozygosity when known; do not invent a universal genotype-based starting-dose formula.','Renal eligibility and dose-table wording require specialist reconciliation; normal current results cannot bypass a recorded contraindication or permanent stop.','The source recovery requirement for delayed diarrhoea is strict; keep previous maximum severity, actual recovery date, cycle-day history and prescribed restart distinct.','Adult loperamide and cefixime reference doses are not paediatric prescriptions. '+DIARRHOEA_CLINICIAN]+(['The temozolomide escalation text and footnote differ at grade 3. Grade 3 toxicity must not automatically pass escalation; the actual 125 or 150 mg/m² starting level determines the reduction column.','The day-34 review rule belongs to the recorded intended cycle start and must not be erased by resetting the calendar.']if vit else['The source day-35/one-week wording is internally inconsistent; do not silently convert it into an invented recovery deadline.','Do not import the vincristine-containing regimen’s missed-dose or temozolomide escalation rules.']),tests=[test('Full blood count','Detect infection, anaemia and bleeding risks from both medicines.','At baseline and before each cycle. Current irinotecan product information recommends weekly blood counts during treatment; the team gives exact sampling dates and any additional tests.','blood','routine',['nccp','irinotecan-pi']),test('Kidney function and hydration','Identify dehydration and impaired clearance during bowel illness.','At baseline and before each cycle; urgent extra tests may be needed during diarrhoea, vomiting, reduced urine or poor intake.'),test('Liver tests','Detect liver injury and guide safe dosing.','At baseline and before each cycle; arrange additional tests during or after treatment when product guidance, symptoms or abnormal results indicate them. Delayed liver toxicity remains possible.','blood','routine',['nccp','temozolomide-pi']),test('Hepatitis B screening and follow-up','Identify infection that can reactivate during treatment.','Screen before treatment. Positive results require expert review and a monitoring/prevention plan during and after treatment.','blood','routine',['nccp','temozolomide-pi']),test('Bowel function and infection review','Distinguish acute irinotecan reactions from delayed diarrhoea and recognise infection.','Review before treatment and before restarting after a hold. Record the worst diarrhoea, recovery date, fever, oral intake and urine output; contact oncology promptly when symptoms begin.','review')]+([test('Blood glucose','Record baseline metabolic status.','Check before treatment as listed in the national source; repeat when clinically indicated. No routine interval is invented.'),test('Nerve function and constipation','Identify vincristine effects before further exposure.','Review at each cycle and before every vincristine dose, including day 8. Report weakness, sensory changes, walking difficulty or severe constipation.','review')]if vit else[]),summary_monitoring=[summary('Bloods','Full blood count','Before treatment and each cycle; weekly counts during treatment follow irinotecan product advice.','Regimen / product'),summary('Bloods','Kidney and liver tests','Before treatment and each cycle; extra tests for diarrhoea, dehydration, symptoms or abnormal results.','Regimen / product'),summary('Infection','Hepatitis B'+(' and baseline glucose'if vit else''),'Before treatment. Positive hepatitis B needs specialist follow-up.'),summary('Checks','Bowel function'+(' and nerves'if vit else''),'Report diarrhoea immediately; review recovery before restart.'+(' Check nerves before every vincristine dose.'if vit else'')),summary('Review','Tumour and symptoms','Scans and clinical-review dates follow the specialist treatment plan.','Individual plan')],missed=missed,wider_sources=['nci-rms'if vit else'nci-ewing'])
 out['00754']=dict(title='Ifosfamide, vincristine, dactinomycin and doxorubicin',context='High-risk or very-high-risk rhabdomyosarcoma in people younger than 40 years',purpose='Treat rhabdomyosarcoma throughout the body as part of an individual specialist plan that also addresses local tumour control. The team explains why this combination is selected for your risk group and priorities.',days=21,kind='phased-cycles',label='9 cycles every 21 days · three different phases',agents=[copy.deepcopy(a[n])for n in ['ifosfamide','vincristine','dactinomycin','doxorubicin']],schedule='Nine cycles are planned every 21 days. In cycles 1–2, vincristine is given on days 1, 8 and 15; doxorubicin on days 1 and 2; dactinomycin on day 1; and ifosfamide on days 1 and 2. In cycles 3–4, vincristine is given only on day 1, with the other three drugs on the same days as before. In cycles 5–9, doxorubicin is omitted; day-1 vincristine/dactinomycin and day-1/2 ifosfamide continue. Use the correct phase chart for your actual cycle.',administration='Vincristine 1.5 mg/m², maximum 2 mg, is given by an intravenous minibag over 15 minutes. Dactinomycin 1.5 mg/m², maximum 2 mg, and doxorubicin 30 mg/m² on each of days 1 and 2 are administered by trained staff as intravenous boluses. Ifosfamide 3000 mg/m² on each of days 1 and 2 is infused over three hours. Mesna, fluids, safety review and observation add to the attendance or admission time.',baseline='Full blood count, kidney and liver profile and heart pumping assessment by ultrasound or a pumping scan. Review nerve function, urine, previous anthracycline exposure, infection, medicines, fertility and the local-treatment plan.',monitoring='Blood count, kidney and liver tests before each cycle. Neurological assessment before each ifosfamide dose and urine blood checks before each dose and every 8 hours on treatment days. Review peripheral neuropathy before each cycle and before further vincristine; repeat heart function testing when indicated.',support='Ifosfamide gives all three phases a high nausea/vomiting risk; use one prescribed anti-sickness plan and review aprepitant interactions. On each of days 1 and 2, the current source specifies mesna 900 mg/m² intravenously over ten minutes immediately before ifosfamide, then 3000 mg/m² continuously over 24 hours starting with ifosfamide. '+FLUIDS+' White-cell growth factor is prescribed on days 4–7 and 9–11 in cycles 1–2 at 5 micrograms/kg. In cycles 3–9, pegylated growth factor may be considered from day 4. Provide constipation prevention, mouth care and individual tumour-lysis prevention; consider Pneumocystis jirovecii pneumonia and antifungal prevention according to the specialist plan, avoiding interacting azoles with vincristine.',prep='Confirm whether this is cycle 1–2, 3–4 or 5–9, and which vincristine appointments and doxorubicin doses apply. Check the full mesna/hydration prescription and the growth-factor calendar. Ask about individual infection prevention, bowel support and medicines that may interact.',access=ACCESS,wider='Rhabdomyosarcoma treatment combines systemic therapy with local treatment tailored to tumour site, risk and feasible surgery and/or radiotherapy. The multidisciplinary team coordinates these components. The choice of an additional anthracycline requires a separate benefit–risk discussion because the randomised evidence in high-risk non-metastatic disease did not demonstrate a significant event-free-survival benefit from adding doxorubicin.',scope='This is the nine-cycle regimen for high-risk or very-high-risk rhabdomyosarcoma under age 40, with performance status 0–2. It is not one unchanged calendar repeated nine times. Current mesna timing and the different early versus later growth-factor plans are part of the source-specific prescription. Product licensing and the reason for each selected medicine must be reviewed locally.',trial='EpSSG RMS2005: adding doxorubicin to ifosfamide, vincristine and dactinomycin',trial_url='https://pubmed.ncbi.nlm.nih.gov/29941280/',evidence='A randomised trial in high-risk non-metastatic rhabdomyosarcoma compared the three-drug backbone with the addition of doxorubicin during the first four cycles. It did not show a statistically significant improvement in event-free survival, and serious infections were more common with doxorubicin. Treatment selection therefore needs an individual explanation, not a claim of established extra benefit for everyone.',caveat='The trial enrolled patients older than six months and younger than 21 years with non-metastatic disease; it does not directly establish benefit across the national under-40 or very-high-risk population. The trial used a four-hour doxorubicin infusion rather than the national bolus instruction. Do not claim superiority or transfer the trial outcome to every patient.',doses=[('ifosfamide','Ifosfamide',1,2,'Shown for all phases; use the separate charts for the other medicines.')],phases=[('early','Cycles 1–2',['Ifosfamide','Vincristine','Dactinomycin','Doxorubicin'],'high'),('middle','Cycles 3–4',['Ifosfamide','Vincristine','Dactinomycin','Doxorubicin'],'high'),('late','Cycles 5–9: no doxorubicin',['Ifosfamide','Vincristine','Dactinomycin'],'high')],course='9 cycles, with safety and response review',urgent='New confusion, unusual drowsiness or seizures, blood in urine, very little urine, severe constipation, new weakness or breathlessness requires urgent assessment. Report infusion-site burning immediately.',boundaries=['Vincristine days 8 and 15 apply only to cycles 1–2. Doxorubicin applies only to cycles 1–4; the planned programme supplies 240 mg/m² before accounting for previous exposure. The source lifetime context is 450 mg/m², not the separate IE/VAC 375 mg/m² ceiling.','Mesna 900 mg/m² before and 3000 mg/m² continuously applies separately to each day-1 and day-2 ifosfamide dose in current version 3. Do not copy the older mesna schedule.','Ifosfamide neurological toxicity grade 3 or greater stops that component under this source; do not import the alternating regimen’s potential reintroduction wording.','Pneumocystis and antifungal prophylaxis are considered individually here, unlike mandatory Pneumocystis prevention with temozolomide.','Current dactinomycin source review found the historical Irish Cosmegen licence withdrawn in 2012; that does not withdraw this national regimen. Pharmacy must verify the actual supplied product, access and licensing, with product-specific consent.'],tests=[test('Full blood count','Identify infection-fighting cell, haemoglobin and platelet changes.','Before treatment and each cycle; additional samples are directed by symptoms, treatment admission and count recovery.'),test('Kidney and liver tests','Check safe drug handling and identify organ toxicity.','Before treatment and each cycle; repeat sooner for symptoms, fluid changes or abnormal results.'),test('Heart pumping and previous anthracyclines','Assess risk from doxorubicin.','Heart ultrasound or pumping scan before treatment; repeat when clinically indicated. Review symptoms and total previous anthracycline exposure before further doxorubicin.','procedure'),test('Neurological function','Detect ifosfamide effects on alertness and vincristine nerve toxicity.','Check neurological function before every ifosfamide dose; review peripheral neuropathy before every cycle and before further vincristine. Report new weakness, sensory changes or altered alertness immediately.','review'),test('Urine and fluid balance','Detect bladder bleeding, kidney effects or fluid retention.','Check urine for blood before each ifosfamide dose and every 8 hours on treatment days. Monitor urine output and fluid balance; record daily weight during prescribed hydration.','review'),test('Bowel, mouth and infection review','Detect constipation, ulcers and infection requiring a change in care.','Review before further dosing and report symptoms between visits. The team confirms prophylaxis and growth-factor timing for the current phase.','review')],summary_monitoring=[summary('Bloods','Blood count, kidney and liver','Before treatment and each cycle; extra tests if symptoms or results change.'),summary('Heart','Heart pumping and previous doses','Heart ultrasound or pumping scan before treatment; repeat when indicated.'),summary('Checks','Alertness and nerve function','Before every ifosfamide dose; review nerves before further vincristine.'),summary('Checks','Urine, fluid balance and weight','Urine before each ifosfamide dose and every 8 hours on treatment days; fluid balance and daily weight.'),summary('Review','Tumour and local-treatment plan','Scans, surgery and radiotherapy reviews follow your specialist plan.','Individual plan')],phase_cycles=ivado_calendar(),wider_sources=['nci-rms'])
 for code,f in out.items():
  f['anatomy']=anatomy(code)
  if code in ['00675','00747','00754']:
   f['boundaries'].append('Current Irish Mitoxana 1 g product information (11 September 2023) lists stricter organ contraindications than the national ifosfamide dose tables: serum creatinine above 120 micromol/L, bilirubin above 17 micromol/L, or transaminases/alkaline phosphatase above 2.5 times the upper limit of normal. Confirm the actual supplied product and oncology/pharmacy reconciliation; do not assume a different product or replace the national table with a universal new dose rule.')
  f['tests'].append(test('Tumour response and local-treatment review','Assess benefit separately from treatment safety.','The specialist sets scans and clinical reviews according to tumour type, disease extent, symptoms and any surgery or radiotherapy plan.','scan','conditional'))
 return out
